$check(count($administration->options($owner)['policies'])>0,'Personal policy administration lists visible versions');
$check($http(null,'GET','/reference/custom/spell-policies')->getStatusCode()===401,'Policy administration requires authentication');
$check($http($owner,'GET','/reference/custom/spell-policies')->getStatusCode()===200,'Personal administration API loads');
$check($http($owner,'GET','/admin/reference/spell-policies')->getStatusCode()===403,'Official policy screen requires admin');
$check($http($admin,'GET','/admin/reference/spell-policies')->getStatusCode()===200,'Official policy screen renders');
$check($http($admin,'POST','/admin/reference/spell-policies',[])->getStatusCode()===403,'Official policy form rejects missing CSRF');
