$check($http($owner,'GET','/characters/'.$subCharacter->getId().'/spell-substitutions')->getStatusCode()===200,'Owner can inspect substitution history');
$options=$administration->options($owner);
$document=$options['example']; $document['sourceId']=$bookClass->getId();
$check($http($owner,'POST','/reference/custom/spell-policies',$document)->getStatusCode()===403,'Personal API cannot create official policies');
$document['sourceType']='subclass'; $document['sourceId']=$customSub->getId();
$document['policy']['version']=100; $document['policy']['key']='administration-fixture';
$check($http($owner,'POST','/reference/custom/spell-policies',$document)->getStatusCode()===201,'Owner can create a version for a personal source');
$check($http($other,'POST','/reference/custom/spell-policies',$document)->getStatusCode()===404,'Foreign policy source remains hidden');
