for ($n=1;$n<=12;++$n) { $l=new App\Entity\CharacterClassLevel($castCharacter,$castClass,$n); $castCharacter->addClassLevel($l); $em->persist($l); }
$em->flush();
$castLevels=array_map(static fn($l)=>$l->getId(),$castCharacter->getClassLevels()->toArray());
