$castSpells=[];
foreach ([6,6,0,0] as $i=>$level) $castSpells[]=$catalogue->create(array_replace($fixture,['slug'=>'cast-fixture-'.$i,'level'=>$level,'classIds'=>[$castClass->getId()]]),$admin,true);
