$adminDocument['sourceId']=$castClass->getId(); $adminDocument['policy']['version']=2; $adminDocument['policy']['key']='admin-form-fixture';
$postForm=static function(array $form) use ($session,$kernel) {
    $request=Symfony\Component\HttpFoundation\Request::create('/admin/reference/spell-policies','POST',$form,[$session->getName()=>$session->getId()]);
    $request->setSession($session);
    return $kernel->handle($request);
};
$form=['_token'=>html_entity_decode($tokenMatch[1]),'kind'=>'policy','document'=>json_encode($adminDocument)];
$response=$postForm($form);
$check($response->getStatusCode()===303,'Official policy form creates a version with PRG');
