$invalidForm=$form; $invalidForm['document']='{"broken":';
$response=$postForm($invalidForm);
$check($response->getStatusCode()===400 && str_contains($response->getContent(),'broken'),'Invalid policy form preserves draft');
$officialGrant=$grants->save($spells[3]['id'],null,['subclassId'=>$advancedSub->getId(),'mode'=>'grant-known','unlockLevel'=>3,'castingClassId'=>$advancedClass->getId(),'quotaImpact'=>'free'],$admin,true);
$officialRule=array_replace($subRuleData,['grantId'=>$officialGrant['id'],'budgetKey'=>'official-substitution']);
$form['kind']='substitution'; $form['document']=json_encode($officialRule);
$check($postForm($form)->getStatusCode()===303,'Official substitution configuration is administered with CSRF and PRG');
