foreach ([App\Entity\SpellGrantSubstitutionRule::class,App\Entity\CharacterSpellSubstitution::class] as $type) {
    $meta=$em->getClassMetadata($type); $actual=$db->createSchemaManager()->introspectTable($tempSchema.'.'.$meta->getTableName());
    $expected=$schema->getSchemaFromMetadata([$meta])->getTable($meta->getTableName());
    $check($db->createSchemaManager()->createComparator()->compareTables($actual,$expected)->isEmpty(),'Substitution migration matches '.$type);
}
$joinSchema=$schema->getSchemaFromMetadata([$em->getClassMetadata(App\Entity\SpellGrantSubstitutionRule::class)]);
$check($db->createSchemaManager()->createComparator()->compareTables($db->createSchemaManager()->introspectTable($tempSchema.'.spell_grant_substitution_list'),$joinSchema->getTable('spell_grant_substitution_list'))->isEmpty(),'Substitution list join migration matches ORM');
